    { "theme": "Fases da Lua e eclipses", "curriculumCode": "EF08CI12", "description": "Construção de modelos, incluindo ferramentas digitais, a partir da observação da Lua no céu, para explicar as fases lunares e os eclipses com base nas posições relativas entre Sol, Terra e Lua.", "materials": ["Bolas de isopor de tamanhos diferentes", "Lanterna", "Palitos de churrasco", "Registro de observação da Lua ao longo de semanas", "Aplicativo ou simulador digital (se disponível)"], "steps": ["Solicitar previamente que os estudantes observem e registrem a aparência da Lua em dias diferentes.", "Socializar os registros de observação e identificar o padrão das fases lunares.", "Montar um modelo físico com bolas de isopor e lanterna representando Sol, Terra e Lua.", "Movimentar o modelo para reproduzir as diferentes fases da Lua.", "Usar o mesmo modelo para explicar como ocorrem os eclipses solar e lunar.", "Registrar em desenho ou esquema as posições relativas associadas a cada fase e eclipse."] },
    { "theme": "Rotação, translação e as estações do ano", "curriculumCode": "EF08CI13", "description": "Descrição e representação dos movimentos de rotação e translação da Terra, analisando o papel da inclinação do eixo terrestre na ocorrência das estações do ano com uso de modelos tridimensionais.", "materials": ["Globo terrestre ou bola representando a Terra", "Lanterna representando o Sol", "Suporte para inclinar o eixo do globo", "Roteiro de observação do modelo"], "steps": ["Retomar os conceitos de rotação e translação já estudados em anos anteriores.", "Apresentar um modelo tridimensional simples com globo inclinado e lanterna representando o Sol.", "Movimentar o globo em torno da lanterna simulando a translação.", "Relacionar a inclinação do eixo terrestre à variação de incidência de luz solar.", "Associar as observações do modelo à ocorrência das estações do ano.", "Registrar as conclusões em um esquema com as quatro estações."] },
    { "theme": "Por que os climas variam entre as regiões", "curriculumCode": "EF08CI14", "description": "Relação entre os climas regionais e os padrões de circulação atmosférica e oceânica, associados ao aquecimento desigual causado pela forma e pelos movimentos da Terra.", "materials": ["Mapa-múndi com zonas climáticas", "Imagens de correntes atmosféricas e oceânicas", "Roteiro de análise em grupo"], "steps": ["Apresentar um mapa-múndi destacando diferentes zonas e tipos de clima.", "Discutir por que regiões próximas à linha do Equador e aos polos recebem quantidades diferentes de luz solar.", "Introduzir noções básicas de circulação atmosférica e correntes oceânicas.", "Relacionar, em grupos, um clima regional específico aos padrões de circulação estudados.", "Apresentar as relações encontradas para a turma."] },
    { "theme": "Entendendo a previsão do tempo", "curriculumCode": "EF08CI15", "description": "Identificação das principais variáveis envolvidas na previsão do tempo, como temperatura, umidade e pressão, com simulação de situações em que elas podem ser medidas.", "materials": ["Termômetro simples", "Higrômetro ou material para higrômetro caseiro", "Imagens de mapas de previsão do tempo", "Roteiro de registro de dados"], "steps": ["Apresentar uma previsão do tempo real e identificar as informações nela contidas.", "Explicar de forma simples o que são temperatura, umidade e pressão atmosférica.", "Organizar, se possível, uma medição simples de temperatura e umidade no pátio da escola.", "Registrar os dados coletados e compará-los com a previsão oficial do dia.", "Discutir em grupo como essas variáveis são usadas para elaborar previsões do tempo.", "Produzir um pequeno boletim de previsão do tempo fictício."] },
    { "theme": "Mudanças climáticas e equilíbrio ambiental", "curriculumCode": "EF08CI16", "description": "Discussão de iniciativas que contribuam para restabelecer o equilíbrio ambiental, a partir da identificação e análise de alterações climáticas regionais e globais provocadas pela ação humana.", "materials": ["Reportagens sobre eventos climáticos extremos", "Gráficos simples sobre variação de temperatura", "Cartolina para proposta de iniciativa"], "steps": ["Apresentar exemplos de alterações climáticas regionais e globais noticiadas recentemente.", "Discutir em grupos possíveis causas humanas associadas a essas alterações.", "Analisar um gráfico simples de variação de temperatura ao longo do tempo.", "Pesquisar iniciativas voltadas à mitigação das mudanças climáticas.", "Selecionar coletivamente uma iniciativa viável para propor na escola.", "Apresentar a proposta em um cartaz ou roda de conversa final."] }
